import csv
import io
import re

def parse_csv(raw_csv: str):
    if not raw_csv:
        return {"columns": [], "rows": []}

    raw_csv = raw_csv.lstrip("\ufeff")
    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",",
                                  quotechar='"', skipinitialspace=True))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = [value.strip() for value in records[0]]
    if columns:
        columns[0] = re.sub(r"^#\s*", "", columns[0])

    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "column_" + str(number)
        while name in used:
            number += 1
            name = "column_" + str(number)
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
